#include <stdio.h>
#include <stdbool.h>
#include <string.h>

bool judgeCircle(const char *moves) {
    int x = 0;
    int y = 0;

    for (int i = 0; moves[i] != '\0'; ++i) {
        if (moves[i] == 'R') ++x;
        else if (moves[i] == 'L') --x;
        else if (moves[i] == 'U') ++y;
        else --y; /* 'D' under the problem constraints */
    }

    return x == 0 && y == 0;
}

